			ids := tagStreams[t.ID]
			out = make([]LivestreamResp, 0, len(ids))
			for i := len(ids) - 1; i >= 0; i-- {
				out = append(out, streamResp(streams[ids[i]]))
			}
		}
		mu.RUnlock()
	} else {
		limit, err := limitParam(c)
		if err != nil {
			return err
		}
		mu.RLock()
		n := len(streamList)
		if limit >= 0 && limit < n {
			n = limit
		}
		out = make([]LivestreamResp, 0, n)
		for i := len(streamList) - 1; i >= 0 && len(out) < n; i-- {
			out = append(out, streamResp(streamList[i]))
		}
		mu.RUnlock()
	}
	if out == nil {
		out = []LivestreamResp{}
	}
	return c.JSON(http.StatusOK, out)
}

