	"net"
	"os"
	"strings"
	"sync"

	"github.com/miekg/dns"
)

var (
	dnsAddr    = "10.99.0.11"
	zoneNames  = map[string]bool{}
	zoneMu     sync.RWMutex
	dnsDropNX  = os.Getenv("DNS_DROP_NX") == "1"
	dnsTTL     = uint32(3600)
	userDnsIP  net.IP
	apexDnsIP  net.IP
)

const zone = "u.isucon.dev."

func loadZoneNames() {
	f, err := os.Open("../pdns/u.isucon.dev.zone")
	if err != nil {
		log.Printf("zone file: %v", err)
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
